  const bounds = await getGridBounds(page);
  await page.mouse.click(bounds.x + x, bounds.y + y);

  // Wait for at least one bin to be selected
  await expect(page.locator('[data-bin-id][aria-pressed="true"]').first()).toBeVisible({
